eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   webAppTranslations: () => (/* binding */ webAppTranslations)\n/* harmony export */ });\nconst webAppTranslations = {\n    fr: {\n        meta: {\n            title: \"Création de web app sur mesure — Barren, développeur web à Lyon\",\n            description: `Vous avez besoin de plus qu'un site vitrine ? Je conçois et développe des applications web sur mesure à Lyon : espace client, dashboard, outil métier, SaaS.`\n        },\n        hero: {\n            label: \"SERVICE — WEB APP\",\n            headline: \"Votre outil digital,\\nfait sur mesure.\",\n            subline: `Une web app, c'est plus qu'un site. C'est un outil que vos utilisateurs utilisent vraiment — pour gérer, suivre, interagir, produire.`\n        },\n        intro: {\n            heading: \"Site internet ou web app : quelle différence ?\",\n            paragraphs: [\n                `Un site internet, c'est une vitrine. Les visiteurs lisent, regardent, et vous contactent. Une web app, c'est un outil : vos utilisateurs se connectent, font des actions, gèrent des données, et reviennent régulièrement.`,\n                `Si votre activité nécessite de gérer des clients, des commandes, des contenus, des équipes ou des données — vous avez probablement besoin d'une web app plutôt que d'un site.`\n            ]\n        },\n        included: {\n            heading: \"Ce que je construis\",\n            subheading: \"Des applications robustes, pensées pour durer.\",\n            items: [\n                {\n                    number: \"01\",\n                    title: \"Authentification & espace client\",\n                    description: \"Inscription, connexion, gestion de compte, rôles et permissions. Vos utilisateurs accèdent à leur espace personnel de façon sécurisée.\"\n                },\n                {\n                    number: \"02\",\n                    title: \"Dashboard & tableaux de bord\",\n                    description: \"Visualisez vos données en temps réel. Graphiques, indicateurs clés, rapports — une interface claire pour piloter votre activité.\"\n                },\n                {\n                    number: \"03\",\n                    title: \"Base de données & gestion des données\",\n                    description: \"Stockage, organisation et manipulation de vos données métier. Formulaires, listes, filtres, exports — tout ce dont vous avez besoin pour gérer votre contenu.\"\n                },\n                {\n                    number: \"04\",\n                    title: \"Design sur mesure\",\n                    description: `Une interface pensée pour vos utilisateurs : claire, rapide à prendre en main, et cohérente avec votre identité visuelle.`\n                },\n                {\n                    number: \"05\",\n                    title: \"Performance & sécurité\",\n                    description: \"Application rapide, données protégées, HTTPS, sauvegardes. Votre outil est fiable et disponible.\"\n                },\n                {\n                    number: \"06\",\n                    title: \"Accompagnement complet\",\n                    description: `Je vous guide de la définition du projet jusqu'au déploiement. Délai garanti, documentation fournie, support inclus après livraison.`\n                }\n            ]\n        },\n        options: {\n            heading: \"Options disponibles\",\n            items: [\n                {\n                    title: \"Intégrations tierces\",\n                    description: `Connexion à des services externes : emails automatiques, Google Calendar, CRM, SMS, et bien d'autres.`\n                },\n                {\n                    title: \"Paiement en ligne\",\n                    description: \"Intégration Stripe pour accepter des paiements ponctuels ou des abonnements récurrents.\"\n                },\n                {\n                    title: \"Notifications\",\n                    description: \"Emails transactionnels, notifications in-app ou SMS selon vos besoins.\"\n                },\n                {\n                    title: \"Maintenance & évolutions\",\n                    description: `Votre app évolue avec votre activité. Je reste disponible pour ajouter des fonctionnalités ou corriger des problèmes.`\n                }\n            ]\n        },\n        examples: {\n            heading: \"Exemples de projets\",\n            subheading: \"Des idées de ce qu'on peut construire ensemble.\",\n            items: [\n                \"Espace client pour suivre des commandes ou des dossiers\",\n                \"Outil interne de gestion pour une équipe\",\n                \"Plateforme SaaS avec abonnement\",\n                \"Application de réservation ou de planification\",\n                `Dashboard de suivi d'activité ou de données`,\n                \"Outil métier spécifique à votre secteur\"\n            ]\n        },\n        why: {\n            heading: \"Pourquoi travailler avec Barren ?\",\n            paragraphs: [\n                `Développeur freelance basé à Lyon, je conçois des web apps pour des professionnels et des entreprises partout en France et à l'étranger.`,\n                `Pas d'agence, pas d'intermédiaire. Vous travaillez directement avec moi, du cadrage initial au déploiement. Je m'assure que l'outil livré correspond exactement à ce dont vous avez besoin — pas plus, pas moins.`,\n                `Chaque projet commence par une discussion pour bien comprendre votre activité avant d'écrire la première ligne de code. Devis gratuit, sans engagement.`\n            ]\n        },\n        cta: {\n            heading: \"Parlons de votre projet\",\n            subline: \"Vous avez une idée ou un besoin précis ? Décrivez-le moi et je vous réponds sous 24h.\",\n            button: \"Prendre contact →\"\n        }\n    },\n    en: {\n        meta: {\n            title: \"Custom Web App Development — Barren, Freelance Web Developer\",\n            description: \"Need more than a website? I design and build custom web apps in Lyon: client portals, dashboards, internal tools, SaaS platforms.\"\n        },\n        hero: {\n            label: \"SERVICE — WEB APP\",\n            headline: \"Your digital tool,\\nbuilt from scratch.\",\n            subline: `A web app is more than a website. It's a tool your users actually use — to manage, track, interact, and get things done.`\n        },\n        intro: {\n            heading: \"Website or web app: what's the difference?\",\n            paragraphs: [\n                \"A website is a storefront. Visitors read, browse, and contact you. A web app is a tool: users log in, take actions, manage data, and come back regularly.\",\n                \"If your business involves managing clients, orders, content, teams, or data — you probably need a web app, not just a website.\"\n            ]\n        },\n        included: {\n            heading: \"What I build\",\n            subheading: \"Solid applications designed to last.\",\n            items: [\n                {\n                    number: \"01\",\n                    title: \"Authentication & user accounts\",\n                    description: \"Sign up, login, account management, roles and permissions. Your users access their personal space securely.\"\n                },\n                {\n                    number: \"02\",\n                    title: \"Dashboards & data visualization\",\n                    description: \"See your data in real time. Charts, KPIs, reports — a clear interface to run your business.\"\n                },\n                {\n                    number: \"03\",\n                    title: \"Database & data management\",\n                    description: \"Storage, organization, and manipulation of your business data. Forms, lists, filters, exports — everything you need to manage your content.\"\n                },\n                {\n                    number: \"04\",\n                    title: \"Custom interface design\",\n                    description: \"An interface built for your users: clear, easy to learn, and consistent with your visual identity.\"\n                },\n                {\n                    number: \"05\",\n                    title: \"Performance & security\",\n                    description: \"Fast app, protected data, HTTPS, backups. Your tool is reliable and always available.\"\n                },\n                {\n                    number: \"06\",\n                    title: \"Full support\",\n                    description: \"I guide you from scoping to deployment. Guaranteed deadline, documentation included, support after delivery.\"\n                }\n            ]\n        },\n        options: {\n            heading: \"Available options\",\n            items: [\n                {\n                    title: \"Third-party integrations\",\n                    description: \"Connect to external services: automated emails, Google Calendar, CRM, SMS, and more.\"\n                },\n                {\n                    title: \"Online payments\",\n                    description: \"Stripe integration for one-time payments or recurring subscriptions.\"\n                },\n                {\n                    title: \"Notifications\",\n                    description: \"Transactional emails, in-app notifications, or SMS depending on your needs.\"\n                },\n                {\n                    title: \"Maintenance & new features\",\n                    description: `Your app grows with your business. I stay available to add features or fix issues.`\n                }\n            ]\n        },\n        examples: {\n            heading: \"Example projects\",\n            subheading: \"Ideas of what we can build together.\",\n            items: [\n                \"Client portal to track orders or files\",\n                \"Internal management tool for a team\",\n                \"SaaS platform with subscription\",\n                \"Booking or scheduling application\",\n                \"Activity or data tracking dashboard\",\n                \"Custom business tool for your industry\"\n            ]\n        },\n        why: {\n            heading: \"Why work with Barren?\",\n            paragraphs: [\n                \"Freelance developer based in Lyon, I build web apps for businesses and individuals across France and internationally.\",\n                \"No agency, no middleman. You work directly with me, from initial scoping to deployment. I make sure the tool I deliver matches exactly what you need — nothing more, nothing less.\",\n                \"Every project starts with a conversation to understand your business before writing a single line of code. Free quote, no commitment.\"\n            ]\n        },\n        cta: {\n            heading: \"Let's talk about your project\",\n            subline: \"Have an idea or a specific need? Tell me about it and I'll get back to you within 24h.\",\n            button: \"Get in touch →\"\n        }\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./src/lib/webApp.js\n");

